#ifndef BONFYRE_CMS_PAGE_COMPOSER_MARKUP_H
#define BONFYRE_CMS_PAGE_COMPOSER_MARKUP_H
static const char *cms_page_composer_markup =
"<div class=\"ak-wb-strip\"><span>Studio</span><span>Composer</span><span id=\"cmc-where\">Your workspace</span><span class=\"ak-live\" id=\"dirty\">Nothing open</span></div>\n"
"<section class=\"cmc-head\"><div><p class=\"ak-kicker\"><a href=\"/studio\">Studio</a> &middot; Page composition</p><h1>Shape a page people can use.</h1><p class=\"ak-lede\">Arrange the page and its sections together. Saving keeps a draft in your workspace; publishing is the separate, reviewed step that puts it live at your address.</p></div>\n"
"<form id=\"open-form\" class=\"cmc-open\"><label class=\"ak-field\">Page address<input id=\"route\" name=\"route\" placeholder=\"/your-page\" required maxlength=\"127\" pattern=\"/[^?#]*\" list=\"known-pages\"></label><datalist id=\"known-pages\"></datalist><button id=\"open\" class=\"ak-btn\">Open or start a page</button></form></section>\n"
"<div class=\"cmc-tools\"><div class=\"cms-layout-modes\" role=\"group\" aria-label=\"Composition reading layout\"><button type=\"button\" data-cms-layout=\"story\" aria-pressed=\"true\">Story</button><button type=\"button\" data-cms-layout=\"cards\" aria-pressed=\"false\">Cards</button><button type=\"button\" data-cms-layout=\"split\" aria-pressed=\"false\">Split</button><button type=\"button\" id=\"preview-phone\" aria-pressed=\"false\">Phone</button></div><div class=\"ak-actions\"><button id=\"undo\" class=\"ak-btn is-quiet\" disabled>Undo</button><button id=\"redo\" class=\"ak-btn is-quiet\" disabled>Redo</button><button id=\"download\" class=\"ak-btn\" disabled>Download draft</button><button id=\"save\" class=\"ak-btn is-primary\" disabled>Review and save</button><button id=\"publish\" class=\"ak-btn is-primary\" hidden>Publish at your address</button></div></div>\n"
"<div id=\"notice\" class=\"cmc-notice\" role=\"status\" aria-live=\"polite\">Choose a page address to begin.</div>\n"
"<div id=\"desk\" class=\"cmc-desk\" hidden><aside class=\"ak-panel\" aria-label=\"Page outline\"><header><h2>Sections</h2><span class=\"ak-tag is-on\" id=\"cmc-count\">0</span></header><div id=\"outline\"></div><div class=\"actions\"><button id=\"add\" class=\"ak-btn is-primary\">Add section</button><button id=\"up\" class=\"ak-btn\">Move up</button><button id=\"down\" class=\"ak-btn\">Move down</button><button id=\"duplicate\" class=\"ak-btn\">Duplicate</button><button id=\"remove\" class=\"ak-btn is-quiet\">Remove</button></div><p class=\"quiet\">Sections keep their audience, sources and projection when moved.</p></aside>"
"<section class=\"ak-panel cmc-sheet\"><header><h2>Sheet</h2><span class=\"ak-actions\"><button type=\"button\" class=\"ak-btn is-quiet\" data-ak-track data-title=\"This draft, read aloud\" data-by=\"Composer\" data-narrate=\"#canvas\">Listen to the draft</button><span class=\"ak-tag\">Reading preview</span></span></header><article id=\"canvas\" aria-label=\"Reading preview\"></article><p class=\"quiet\">Text and links as a reader sees them. Live tools are checked at their destination.</p></section>"
"<fieldset id=\"inspector\" class=\"ak-panel\"><div id=\"fields\"></div></fieldset></div>\n"
"<dialog id=\"cms-publish\" class=\"cms-review\" aria-labelledby=\"cms-publish-title\"><div class=\"cms-review-head\"><p class=\"eyebrow\">Publish</p><h2 id=\"cms-publish-title\">Put this saved version live</h2><p>Exactly the revision you saved is released to your address. If it changed since, nothing is published.</p></div><div class=\"cms-review-items\"><label class=\"cmc-check\"><input type=\"checkbox\" id=\"publish-rights\"> I have the right to publish everything on this page.</label></div><p id=\"cms-publish-status\" role=\"status\" aria-live=\"polite\"></p><div class=\"cms-review-actions\"><button type=\"button\" id=\"cms-publish-cancel\" class=\"ak-btn\">Not yet</button><button type=\"button\" id=\"cms-publish-confirm\" class=\"ak-btn is-primary\" disabled>Publish</button></div></dialog>\n"
"<dialog id=\"cms-review\" class=\"cms-review\" aria-labelledby=\"cms-review-title\" aria-describedby=\"cms-review-warning\"><div class=\"cms-review-head\"><p class=\"eyebrow\">Source-bound publication review</p><h2 id=\"cms-review-title\">Review the exact composition</h2><p id=\"cms-review-warning\">Only the CMS draft is saved. This does not deploy, publish externally, or grant a new operation.</p><p id=\"cms-review-count\" role=\"status\" aria-live=\"polite\"></p></div><div id=\"cms-review-items\" class=\"cms-review-items\"></div><p id=\"cms-review-status\" role=\"status\" aria-live=\"polite\"></p><div class=\"cms-review-actions\"><button type=\"button\" id=\"cms-review-cancel\">Return to editing</button><button type=\"button\" id=\"cms-review-confirm\" class=\"primary\">Save this reviewed version</button></div></dialog>\n"
"<script>\n"
"(()=>{'use strict';\n"
"const $=id=>document.getElementById(id),copy=x=>JSON.parse(JSON.stringify(x));\n"
"const system=new Set(['id','namespace','created_at','updated_at','published_at']);\n"
"const clean=x=>Object.fromEntries(Object.entries(x||{}).filter(([k])=>!system.has(k)));\n"
"let baseline=null,draft=null,selected=-1,undo=[],redo=[],checkpoint='',busy=false,uncertain=false;\n"
"const siteNs=new URLSearchParams(location.search).get('site')||'';const withSite=u=>siteNs?u+(u.includes('?')?'&':'?')+'site='+encodeURIComponent(siteNs):u;\n"
"const serialized=()=>JSON.stringify(draft),dirty=()=>draft&&serialized()!==checkpoint;\n"
"function say(text){$('notice').textContent=text;}\n"
"function controls(){const changed=dirty();$('dirty').textContent=changed?'Unsaved changes':'Saved version';$('save').disabled=!draft||busy||uncertain||!changed;$('undo').disabled=busy||!undo.length;$('redo').disabled=busy||!redo.length;$('download').disabled=!draft;$('open').disabled=busy;$('route').disabled=busy;$('inspector').disabled=busy;pubState();for(const id of ['add','up','down','remove','duplicate'])$(id).disabled=busy||!draft||(id!=='add'&&(selected<0||(id==='up'&&selected===0)||(id==='down'&&selected===draft.fragments.length-1)));}\n"
"function remember(){undo.push(serialized());if(undo.length>50)undo.shift();redo=[];}\n"
"function change(fn){remember();fn();render();}\n"
"function node(tag,text,klass){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(klass)n.className=klass;return n;}\n"
"function preview(){const c=$('canvas');c.replaceChildren();c.append(node('p',draft.page.eyebrow||'','eyebrow'),node('h2',draft.page.heading||'Untitled page'),node('p',draft.page.lede||''));draft.fragments.forEach((s,i)=>{const section=node('section',undefined,selected===i?'selected':'');section.append(node('p',s.eyebrow||'','eyebrow'),node('h3',s.heading||'Untitled section'),node('p',s.body||''));if(s.href){try{const u=new URL(s.href,location.origin);if(['http:','https:'].includes(u.protocol)){const a=node('a',s.label||'Open link');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';section.append(a);}}catch{}}const proof=[s.source_ref?'Source: '+s.source_ref:'',s.source_digest?'Digest: '+s.source_digest:'',s.evidence_ref?'Evidence: '+s.evidence_ref:'',s.projection_contract?'Projection: '+s.projection_contract:''].filter(Boolean);if(proof.length)section.append(node('p',proof.join(' · '),'cms-projection-proof'));section.append(node('p',[s.slot,s.audience,s.status].filter(Boolean).join(' · '),'quiet'));const edit=node('button','Edit section','cms-edit-section');edit.type='button';edit.onclick=()=>{selected=i;render();$('fields').querySelector('input:not([readonly]),textarea')?.focus();};section.prepend(edit);c.append(section);});if(draft.page.note)c.append(node('p',draft.page.note,'quiet'));}\n"
"function outline(){const o=$('outline');o.replaceChildren();for(const [i,label] of [[-1,'Page introduction'],...draft.fragments.map((s,i)=>[i,`${i+1}. ${s.heading||'Untitled section'}`])]){const b=node('button',label);b.type='button';b.setAttribute('aria-pressed',String(selected===i));b.onclick=()=>{selected=i;render();};o.append(b);}}\n"
"function field(parent,obj,key,label,options={}){const wrap=node('label',label);const current=obj[key];let input;if(options.values){input=node('select');for(const value of [...new Set([current,...options.values].filter(x=>x!==undefined))]){const opt=node('option',value);opt.value=value;input.append(opt);}}else input=node(options.long?'textarea':'input');input.id='field-'+key;input.name=key;input.value=current===undefined?'':typeof current==='object'?JSON.stringify(current):String(current);if(options.number)input.type='number';if(options.readonly)input.readOnly=true;if(options.help)wrap.append(node('small',options.help));let before='';input.addEventListener('focus',()=>{before=serialized();});input.addEventListener('input',()=>{if(options.readonly)return;obj[key]=options.number?Number(input.value):input.value;preview();outline();controls();});input.addEventListener('change',()=>{if(before&&before!==serialized()){undo.push(before);if(undo.length>50)undo.shift();redo=[];}before=serialized();controls();});wrap.append(input);parent.append(wrap);}\n"
"function inspector(){const f=$('fields');f.replaceChildren();const s=selected<0?draft.page:draft.fragments[selected];f.append(node('h2',selected<0?'Page introduction':`Section ${selected+1}`));const common=selected<0?[['title','Browser title'],['heading','Heading'],['eyebrow','Eyebrow'],['lede','Introduction',true],['note','Closing note',true]]:[['heading','Heading'],['eyebrow','Eyebrow'],['body','Section text',true],['label','Link label'],['href','Link destination']];for(const [key,label,long]of common)field(f,s,key,label,{long});const advanced=node('details');advanced.append(node('summary','Audience, sources and projection'));const extras=selected<0?[['door_page','Content group'],['lenses','Live lenses'],['aperture_subject','Action subject'],['aperture_operation','Action operation'],['authenticated_pane','Signed-in pane'],['machine_view','Machine view']]:[['coordinate','Section identity'],['slot','Page slot'],['audience','Audience'],['kind','Section kind'],['source_ref','Source reference'],['source_digest','Source digest'],['evidence_ref','Evidence reference'],['variant_key','Variant'],['semantic_tags','Semantic tags'],['projection_contract','Projection contract'],['notes','Internal notes']];for(const [key,label]of extras)field(advanced,s,key,label,{readonly:key==='coordinate',long:['projection_contract','notes'].includes(key)});field(advanced,s,'status','Projection status',{values:['draft','published','archived'],help:'Published makes this record eligible for its configured projection. This does not deploy a site or grant access.'});f.append(advanced);}\n"
"function render(){if(!draft)return;$('desk').hidden=false;outline();inspector();preview();controls();}\n"
"const layoutButtons=[...document.querySelectorAll('[data-cms-layout]')];\n"
"for(const button of layoutButtons)button.onclick=()=>{const value=button.dataset.cmsLayout;if(!['story','cards','split'].includes(value))return;$('canvas').dataset.cmsLayout=value;for(const b of layoutButtons)b.setAttribute('aria-pressed',String(b===button));};\n"
"$('canvas').dataset.cmsLayout='story';\n"
"$('preview-phone').onclick=()=>{const selected=$('desk').classList.toggle('cms-preview-width-phone');$('preview-phone').setAttribute('aria-pressed',String(selected));$('preview-phone').textContent=selected?'Desktop':'Phone';};\n"
"async function request(path,options={}){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(15000),...options});const text=await r.text();let value;try{value=JSON.parse(text);}catch{throw Error('The CMS returned an unreadable response.');}if(!r.ok)throw Error(value.error||'The CMS could not complete this request.');return value;}\n"
"async function read(route){const x=await request(withSite('/cms/compose/page?route='+encodeURIComponent(route)));if(x.schema!=='bonfyre.page-snapshot.v1'||!x.snapshot||x.snapshot.route!==route||!Array.isArray(x.snapshot.fragments)||!/^[0-9a-f]{64}$/.test(x.digest))throw Error('The page snapshot could not be verified.');return x;}\n"
"function editable(x){return {page:clean(x.snapshot.page),fragments:x.snapshot.fragments.map(clean)};}\n"
"function canonical(x){if(Array.isArray(x))return '['+x.map(canonical).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';return JSON.stringify(x);}\n"
"async function open(route){if(dirty()&&!confirm('Discard the unsaved draft and open this page?'))return;busy=true;controls();say('Opening the complete page…');try{baseline=await read(route);draft=baseline.id?editable(baseline):{page:{route,title:'Untitled page',heading:'Untitled page',status:'draft',machine_view:'authored'},fragments:[]};checkpoint=baseline.id?serialized():'';selected=-1;undo=[];redo=[];uncertain=false;history.replaceState(null,'',withSite('/cms/compose?route='+encodeURIComponent(route)));render();say(baseline.id?'Page opened. Edit its introduction or choose a section.':'New draft. Add an introduction and sections, then save the composition.');}catch(e){say(e.message);}finally{busy=false;controls();}}\n"
"$('open-form').onsubmit=e=>{e.preventDefault();void open($('route').value);};\n"
"$('add').onclick=()=>{if(draft.fragments.length>=512){say('This page has reached the 512-section limit.');return;}change(()=>{draft.fragments.push({coordinate:'section-'+crypto.randomUUID(),page:draft.page.route,slot:siteNs?'showcase':'body',audience:siteNs?'public':'anonymous',kind:siteNs?'profile-story':'copy',semantic_tags:{authoring_v1:{version:1,payload:{}}},projection_contract:{html:true},position:draft.fragments.length,heading:'New section',body:'',status:'draft'});selected=draft.fragments.length-1;});};\n"
"for(const [id,delta]of [['up',-1],['down',1]])$(id).onclick=()=>change(()=>{const other=selected+delta;[draft.fragments[selected],draft.fragments[other]]=[draft.fragments[other],draft.fragments[selected]];selected=other;draft.fragments.forEach((s,i)=>s.position=i);});\n"
"$('remove').onclick=()=>{if(selected<0)return;change(()=>{draft.fragments.splice(selected,1);selected=Math.min(selected,draft.fragments.length-1);draft.fragments.forEach((s,i)=>s.position=i);});};\n"
"$('duplicate').onclick=()=>{if(selected<0||!draft||draft.fragments.length>=512)return;change(()=>{const source=copy(draft.fragments[selected]);source.coordinate='section-'+crypto.randomUUID();source.position=selected+1;source.status='draft';draft.fragments.splice(selected+1,0,source);selected++;draft.fragments.forEach((s,i)=>s.position=i);});};\n"
"for(const [id,from,to]of [['undo',()=>undo,()=>redo],['redo',()=>redo,()=>undo]])$(id).onclick=()=>{to().push(serialized());draft=JSON.parse(from().pop());selected=Math.min(selected,draft.fragments.length-1);render();};\n"
"$('download').onclick=()=>{const blob=new Blob([JSON.stringify({baseline,draft},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download='page-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\n"
"async function saveCurrentPage(){if(!dirty()||busy||uncertain)return;const submitted=copy(draft),route=baseline.snapshot.route;const payload={operation:baseline.id?'replace':'create',route,expected_id:baseline.id,expected_digest:baseline.digest,...submitted};const body=JSON.stringify(payload);if(new TextEncoder().encode(body).length>220000){say('This draft exceeds the browser save limit of 220 KB. Download it before editing further.');return;}busy=true;controls();say('Saving the page and every section…');let acknowledged=null;try{acknowledged=await request(withSite('/cms/compose/page'),{method:'POST',headers:{'Content-Type':'application/json'},body});if(!acknowledged.committed)throw Error('The CMS did not confirm the save.');const actual=await read(route);if(actual.digest!==acknowledged.digest)throw Error('The saved page changed again before readback.');baseline=actual;draft=editable(actual);checkpoint=serialized();undo=[];redo=[];render();say('Composition saved and reopened from the CMS.');}catch(e){try{const actual=await read(route);if(actual.id&&canonical(editable(actual))===canonical(submitted)){baseline=actual;draft=editable(actual);checkpoint=serialized();undo=[];redo=[];render();say('The reply was interrupted, but the CMS confirms your complete composition is saved.');}else{uncertain=true;say('Your draft is still here. The saved page differs from this draft. Download your changes, then reopen the saved version before merging or retrying.');}}catch{uncertain=true;say('The save outcome could not be confirmed. Keep this tab open or download the draft. Reopen the page once the CMS is available before retrying.');}}finally{busy=false;controls();}}\n"
"const reviewDialog=$('cms-review'),reviewList=$('cms-review-items');let reviewed=null;\nconst previewValue=x=>x===undefined?'Not present':x===null?'Empty':typeof x==='object'?JSON.stringify(x):String(x);\nfunction draftChanges(){\n const old=baseline.id?editable(baseline):{page:{},fragments:[]},results=[];\n const fields=(name,before,after)=>{for(const field of new Set([...Object.keys(before||{}),...Object.keys(after||{})])){\n  const a=before?.[field],b=after?.[field];if(canonical(a)===canonical(b))continue;\n  results.push({label:name+' · '+field,before:previewValue(a),after:previewValue(b)});\n }};\n fields('Page introduction',old.page,draft.page);\n const prior=new Map((old.fragments||[]).map((s,i)=>[s.coordinate||'old:'+i,s]));\n const current=new Map(draft.fragments.map((s,i)=>[s.coordinate||'new:'+i,s]));\n for(const [key,section] of current)fields('Section '+(section.heading||key),prior.get(key),section);\n for(const [key,section] of prior)if(!current.has(key))results.push({label:'Removed section · '+(section.heading||key),before:previewValue(section),after:'Not present'});\n return results;\n}\nfunction openSaveReview(){\n if(!dirty()||busy||uncertain||!baseline||reviewDialog.open)return;\n const data=draftChanges();if(!data.length){say('No changed fields to review.');return;}\n reviewed={version:serialized(),digest:baseline.digest,id:baseline.id};reviewList.replaceChildren();\n $('cms-review-count').textContent=data.length+' changed field'+(data.length===1?'':'s')+' in this exact CMS draft. Showing '+Math.min(data.length,120)+'.';\n for(const change of data.slice(0,120)){const row=node('section',undefined,'cms-review-item');row.append(node('h3',change.label));\n  for(const [label,value]of [['Saved',change.before],['Proposed',change.after]]){const cell=node('div');cell.append(node('dt',label),node('dd',value));row.append(cell);}\n  reviewList.append(row);}\n $('cms-review-status').textContent=data.length>120?'Additional changes are not displayed. Download the draft for a complete inspection before saving.':'Review all changes before saving. The CMS will independently check the original digest.';\n $('cms-review-confirm').disabled=data.length>120;reviewDialog.showModal();\n}\n$('save').onclick=openSaveReview;\n$('cms-review-cancel').onclick=()=>reviewDialog.close();\nreviewDialog.addEventListener('close',()=>{reviewed=null;});\n$('cms-review-confirm').onclick=async()=>{\n const state=reviewed;if(!state||!reviewDialog.open||state.version!==serialized()||state.digest!==baseline?.digest||state.id!==baseline?.id){\n  $('cms-review-status').textContent='The saved version or working draft has changed. Return to editing and review again.';return;}\n reviewed=null;reviewDialog.close();await saveCurrentPage();\n};\n"
"function pubState(){const b=$('publish');if(!b)return;const r=baseline&&baseline.snapshot?baseline.snapshot.route:'';b.hidden=!(siteNs&&baseline&&baseline.id&&/^\\/blog\\/[a-z0-9-]+\\/$/.test(r)&&draft&&draft.page.status==='draft');b.disabled=busy||uncertain||dirty();if(draft){$('cmc-count').textContent=String(draft.fragments.length);$('cmc-where').textContent=r||'Your workspace';}}\n"
"const pubDialog=$('cms-publish');$('publish').onclick=()=>{if(!baseline||!baseline.id||dirty())return;$('publish-rights').checked=false;$('cms-publish-confirm').disabled=true;$('cms-publish-status').textContent='';pubDialog.showModal();};\n"
"$('publish-rights').onchange=()=>{$('cms-publish-confirm').disabled=!$('publish-rights').checked;};$('cms-publish-cancel').onclick=()=>pubDialog.close();\n"
"$('cms-publish-confirm').onclick=async()=>{const route=baseline.snapshot.route;busy=true;controls();$('cms-publish-status').textContent='Publishing…';try{await request(withSite('/cms/compose/publish?route='+encodeURIComponent(route)),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_id:baseline.id,expected_digest:baseline.digest,rights_confirmed:true})});pubDialog.close();busy=false;await open(route);say('Published. The page now answers at your address.');}catch(e){$('cms-publish-status').textContent=e.message;}finally{busy=false;controls();}};\n"
"window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});\n"
"request(withSite('/cms/compose/pages')).then(x=>{if(x.has_more)$('route').title='Suggestions show the first 512 pages. Enter an exact address to open another page.';for(const p of x.pages||[]){const option=node('option',p.title);option.value=p.route;$('known-pages').append(option);}}).catch(()=>{});\n"
"const initial=new URLSearchParams(location.search).get('route');if(initial){$('route').value=initial;void open(initial);}\n"
"})();\n"
"</script>\n"
;
#endif
